-- `mailer` module: SMTP senders, one per From address.
CREATE SCHEMA IF NOT EXISTS "mailer";

CREATE TABLE "mailer"."smtp_sender" (
    -- Generated by the application: it is the associated data the
    -- credentials are encrypted with, so it must exist before the insert.
    "id"                 uuid      PRIMARY KEY,
    -- Stable name other modules use to pick the sender, e.g. `noreply`.
    "name"               text      NOT NULL UNIQUE
        CHECK ("name" ~ '^[a-z0-9][a-z0-9_-]{0,62}$'),
    "address"            text      NOT NULL,
    "host"               text      NOT NULL CHECK ("host" <> ''),
    "port"               integer   NOT NULL CHECK ("port" BETWEEN 1 AND 65535),
    "tls_mode"           text      NOT NULL
        CHECK ("tls_mode" IN ('starttls', 'implicit_tls', 'plaintext')),
    -- Ciphertext (`EncryptedString<DefaultSymmetricEncryption>`). Both NULL
    -- for a relay without authentication.
    "username_encrypted" bytea,
    "password_encrypted" bytea,
    "enabled"            boolean   NOT NULL DEFAULT true,
    "remark"             text      NOT NULL DEFAULT '',
    "created_at"         timestamp NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    "updated_at"         timestamp NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    CONSTRAINT "smtp_sender_credentials_paired"
        CHECK (("username_encrypted" IS NULL) = ("password_encrypted" IS NULL))
);
